const test = require('node:test');
const assert = require('node:assert/strict');
const { lowerBound, upperBound } = require('./bounds');

test('a value in the middle of distinct numbers', () => {
  assert.equal(lowerBound([1, 3, 5, 7, 9], 5), 2);
  assert.equal(upperBound([1, 3, 5, 7, 9], 5), 3);
});

test('a value between two elements', () => {
  assert.equal(lowerBound([1, 3, 5, 7, 9], 4), 2);
  assert.equal(upperBound([1, 3, 5, 7, 9], 4), 2);
});

test('edge cases and validation', () => {
  assert.equal(lowerBound([], 5), 0);
  assert.equal(upperBound([], 5), 0);
  assert.equal(lowerBound([1, 2, 2, 2, 3], 2), 1);
  assert.equal(upperBound([1, 2, 2, 2, 3], 2), 4);
  assert.equal(lowerBound([5], 5), 0);
  assert.equal(upperBound([5], 5), 1);

  assert.throws(() => lowerBound('not array', 5), TypeError);
  assert.throws(() => upperBound([1, 2], 'not number'), TypeError);
  assert.throws(() => lowerBound([1, 2], NaN), TypeError);
});
"}
